((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 18, 82.735, 87.946, '이렇게 해서라도 난 너를 만나고 싶어', 'if I could see you again'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 19, 87.946, 91.062, 'lucid한 기분 느껴 보려 해', 'lucid like a dream I wanna feel it'),
