((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 21, 94.588, 97.111, '애매한 퀴즈를 푸는 일', 'solving a riddle but I''m clueless'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 22, 97.111, 103.714, '저 멀리 보인 건 난 걸 비현실적인 REM 속 walkway', 'lost in this made-up REM sleep walkway'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 23, 103.714, 106.133, '알다가도 여긴 또 어디', 'I thought I knew but I don''t know here'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 24, 106.133, 113.711, '더 이상하게 펼쳐진 viewfinder 뒤', 'more unfamiliar in this strange viewfinder screen'),
