((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 29, 126.469, 128.748, '다시 길을 잃어도', 'even if I lose my path'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 30, 128.748, 133.824, '이렇게 해서라도 난 너를 만나고 싶어', 'if I could see you again sure I can take another step'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 31, 133.824, 137.14, 'lucid 한 기분 느껴 보려 해', 'lucid like a dream I wanna feel it'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 32, 138.481, 143.42, '구름 그 위로 몸이 떠올라', 'my body goes up reaching the skyline'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 33, 143.42, 149.028, '이 순간 자유로운 난 moonlight', 'higher than clouds shining down like moonlight'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 34, 149.028, 153.251, '어떤 길도 상관없어', 'which way who cares doesn''t matter'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 35, 153.251, 154.713, '(어떤 palace)', '(any palace)'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 36, 154.713, 159.504, '뚫고서 네게 날아가', 'cuz I can just fly straight to you'),
