((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 43, 177.16, 178.522, 'lucid한 기분', 'lucid like a dream'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 44, 178.522, 179.96, 'lucid한 moment', 'lucid like moment'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 45, 179.96, 182.498, '녹아내린 어제도', 'turn away from yesterday'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 46, 182.498, 185.315, '닿지 않는 내일도', 'let tomorrow take my hand'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 47, 185.315, 188, '나를 속이고 숨겨 안갯속 규칙', 'fool me once fool me twice gonna find out the rules'),
((SELECT id FROM videos WHERE youtube_id = '7GU_VQfgMT0'), 48, 188, 190.02, '갇힌다 해도 갈래', 'I won''t be locked in again'),
