INSERT INTO videos (youtube_id, title, channel_name, channel_id, duration, language1, language2)
INSERT INTO captions (video_id, idx, begin, end, text1, text2) VALUES
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 0, 0.873, 2.999, '안녕하세요, 시온입니다.', 'Hi, it''s Shion.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 1, 3.269, 7.975, '오늘은 2월 11일 수요일이고요.', 'Today is Wednesday, February 11th.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 2, 8.519, 14.581, '저는 지금 영통 팬사를 끝나고 이렇게 영상 일기를 찍고 있습니다.', 'I just finished a video fan sign and now I''m filming this video diary.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 3, 15.28, 20.954, '오랜만에 이렇게 영상 일기로 찾아뵙는 거 같은데요. 여러분들 보고 싶으셨죠?', 'It feels like it''s been a while since I did a video diary. You all missed me, right?'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 4, 21.96, 23.869, '그렇다고 하세요!', 'Tell me you missed me!'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 5, 25.41, 31.893, '약간 이제 컴백 이후로 영상 일기가 처음인 거 같은데요.', 'I think this is my first video diary since our comeback.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 6, 33.399, 36.498, '최근에 또 할 얘기가 엄청 많아요.', 'There''s so much I''ve been wanting to tell you lately.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 7, 36.69, 42.443, '최근에 제가 또 대전에 시그널 찍으러 빵 투어를 갔잖아요.', 'Recently, we went to Daejeon to film the bread tour episode of SIGNAL.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 8, 42.943, 48.419, '뭔가 시그널 찍으러 근처로는 많이 갔는데', 'We often travel nearby for SIGNAL shoots,'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 9, 48.421, 53.354, '대전까지 간 적은 진짜 처음이라서 되게 놀랐고', 'but it was my first time going all the way to Daejeon, and I was really surprised.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 10, 53.773, 57.205, '처음에 이제 스케줄표에 대전 빵 투어 이렇게 있어서', 'When I saw "Daejeon Bread Tour" on the schedule,'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 11, 57.208, 69.792, '멤버들도 그렇고 저도 그렇고 약간 대전 지점, 약간 대전 가게의 서울 지점 이런 빵집 투어인 줄 알았는데', 'the members and I thought it meant visiting Seoul branches of bakeries originally from Daejeon.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 12, 70.027, 77.822, '진짜 성심당도 가고 근처에 맛집도 가고 이렇게 해서 되게 놀랐던 시그널 촬영이었고요.', 'But we actually got to visit Seongsimdang and other famous local spots nearby.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 13, 79.119, 86.397, '되게 신유 언니도 그렇고 하연이도 그렇고 되게 뿌듯해하고 즐거워했던 촬영이었던 거 같습니다.', 'I think Xinyu unnie and HaYeon were really satisfied and had a lot of fun too.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 14, 87.476, 93.612, '뭔가 오랜만에 대전을 촬영으로 가게 돼서 반갑기도 했고', 'It made me so happy to visit Daejeon for filming after such a long time.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 15, 94.089, 105, '그 거리에서 진짜 지나가는데 저희 타이틀곡도 아닌데 진짜 불꽃놀이가 들린 거예요.', 'While we were walking around the city, "Firework Diary" started playing, even though it''s not the title track.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 16, 105.085, 113.313, '진짜 그 편의점 앞에서 갑자기 진짜 불꽃놀이 인트로가 바로 들렸어요.', 'Out of nowhere, I heard the intro of "Firework Diary" in front of a convenience store.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 17, 113.316, 121.047, '그래서 이거 뭐지? 진짜 너무 당황스러웠는데 뭔가 감사했던 일이었어요.', 'I was like, "Wait, what?" and totally shocked, but also so grateful.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 18, 121.05, 125.792, '진짜 이거는 운명인 거 같아요. 진짜 대박!', 'I honestly felt like it was fate. It was the best!'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 19, 126.692, 135, '그리고 또 빵 라이브 했던 것도 되게 의미 있었던 거 같고', 'Also, the bread-themed live stream we did before was such a meaningful time.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 20, 135.625, 141.308, '요즘 뭔가 되게 빵 관련해서 많이 찍어서 되게 신기했던 거 같아요.', 'Lately, we''ve been filming a lot of bread-related content, and it feels kind of surreal.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 21, 141.612, 150.217, '뭔가 갑자기 제가 내가 박시온인지 빵시온인지 약간 헷갈리는 그런 느낌이었고요.', 'I almost couldn''t tell if I was Park ShiOn or "Bread ShiOn."'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 22, 150.383, 154.578, '또 요즘에 저희 콘서트 준비도 열심히 하고 있는데요.', 'And recently, we''ve been working really hard preparing for the concert.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 23, 154.967, 162.859, '멤버들도 말했다시피 진짜 콘서트 셋리가 예전이랑 좀 많이 다를 거고', 'Like the members mentioned, this concert''s setlist is a bit different from before.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 24, 162.862, 169.091, '또 그것만큼 저희가 알차게 준비를 하고 있으니까 다들 많이 기대해 주시고', 'We''re putting together something even more special, so please look forward to it.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 25, 169.229, 179.212, '또 기대 많이 해 주시는 것 같은데 그만큼 저희가 웨이브 분들이 만족할 수 있게끔 열심히 준비를 해 보도록 하겠습니다.', 'I know WAV is really excited, and we''ll work hard to live up to your expectations.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 26, 182.296, 191.152, '또 오가는 길도 안전하게 저희 모두 다 다녀올 테니까요.', 'We''ll make sure to travel safely to and from the venue,'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 27, 191.374, 195.642, '웨이브 분들도 항상 조심하시고', 'so WAV, please stay safe too.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 28, 195.642, 202.35, '요즘 날씨도 되게 추운데 감기도 독감도 모두 조심하세요. 아시겠죠?', 'It''s been really cold lately, so be careful not to catch a cold or the flu, okay?'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 29, 203.864, 215.36, '그리고 또 오랜만에 문 유닛이랑 같이 연습을 하니까 또 되게 새롭더라고요. 재밌기도 하고', 'Also, we''ve been practicing as the moon unit again, and it feels really fresh and fun.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 30, 215.478, 220.759, '저희 문 유닛이 되게 어이가 없게 웃긴 멤버들이 다 모여 있거든요.', 'The moon unit has such uniquely funny members in the most unexpected ways.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 31, 221.079, 228.006, '그래서 진짜 이 케미를 웨이브 여러분들께 진짜 보여 드리고 싶은데 되게 아쉬운 거 같아요.', 'So it''s a bit of a shame that we can''t show that chemistry to WAV yet.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 32, 228.009, 230.541, '진짜 웨이브 분들도 아시긴 하겠지만', 'I''m sure you already know,'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 33, 230.543, 236.11, '진짜 그 연습실에서 웨이브도 같이 있었으면 좋겠다는 그런 마음이 큰 거 같습니다.', 'but there are so many times in the practice room when I think, "I wish WAV could be here with us."'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 34, 237.434, 241.057, '뭔가 콘서트 준비를 하고 있는데', 'As we prepare for the concert,'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 35, 241.06, 245.103, '처음에는 준비해야 될 게 너무 많아서 걱정이 많이 됐었어요.', 'at first, it felt overwhelming because there was so much to do.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 36, 245.494, 254.654, '최대한 진짜 최고치를 끌어올리고 싶고 정말 열심히 준비해서 좋은 무대를 보여 드리고 싶습니다.', 'But we want to bring everything to the best possible level and show you an amazing stage.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 37, 255.72, 260.527, '그 귀한 시간이 정말 아깝지 않도록 보여 드리고 싶어요.', 'I want this concert to be a performance that makes your precious time truly worthwhile.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 38, 261.695, 266.328, '그러면 이번 영상 일기도 여기서 마치도록 하겠습니다.', 'That''s it for today''s video diary.'),
((SELECT id FROM videos WHERE youtube_id = 'DtK-CkwNHSY'), 39, 266.932, 271.705, '봐주신 분들 너무 감사합니다. 안녕!', 'Thank you so much to everyone who watched. Bye!');
